#include "KS/SRC/ks/FEPanel_shared.h"

inline bool operator==(const stringx &lhs, const stringx &rhs)
{
    struct access { char *chars; string_buf *my_buf; };
    const string_buf *left = reinterpret_cast<const access *>(&lhs)->my_buf;
    const string_buf *right = reinterpret_cast<const access *>(&rhs)->my_buf;
    if (right->block_length != left->block_length)
        return false;
    for (int i = 0; i < left->block_length; i++)
        if (right->data[i] != left->data[i])
            return false;
    return true;
}

PanelGeom *PanelGeom::FindObject(const stringx &search_name)
{
  if (name == search_name)
    return this;
  else
  {
    PanelGeom *temp;
    if (children)
    {
      temp = children->FindObject(search_name);
      if (temp && temp->name == search_name)
        return temp;
    }
  }

  return NULL;
}
